import{_ as o,C as i,o as e,c as n,a4 as a,b as s,w as r,a as d,E as h,a5 as g}from"./chunks/framework.9tZL7ZIQ.js";const C=JSON.parse('{"title":"伯克希尔账面价值 · 从1900万到万亿帝国","description":"","frontmatter":{},"headers":[],"relativePath":"06_visualization/book-value-growth.md","filePath":"06_visualization/book-value-growth.md"}'),c={name:"06_visualization/book-value-growth.md"};function p(u,t,_,m,x,b){const l=i("Mermaid");return e(),n("div",null,[t[1]||(t[1]=a('<h1 id="伯克希尔账面价值-·-从1900万到万亿帝国" tabindex="-1">伯克希尔账面价值 · 从1900万到万亿帝国 <a class="header-anchor" href="#伯克希尔账面价值-·-从1900万到万亿帝国" aria-label="Permalink to &quot;伯克希尔账面价值 · 从1900万到万亿帝国&quot;">​</a></h1><p>1965年巴菲特接管伯克希尔时，每股账面价值约19美元。六十载光阴，这家原本濒临破产的纺织厂，成长为由保险帝国与投资组合双轮驱动的万亿巨擘。截至2024年，伯克希尔A股（B shares）每股账面价值已突破<strong>404,800美元</strong>——约是接手时的21,300倍。</p><div class="tip custom-block"><p class="custom-block-title">数据说明</p><p>除特别注明外，本页数据均来源于伯克希尔·哈撒韦年报及公开市场资料，部分历史数据为合理估算。</p></div><h2 id="账面价值增长图" tabindex="-1">账面价值增长图 <a class="header-anchor" href="#账面价值增长图" aria-label="Permalink to &quot;账面价值增长图&quot;">​</a></h2><p>以下图表展示伯克希尔每股账面价值（换算为千美元）在关键年份的变迁，清晰呈现指数级增长轨迹：</p>',5)),(e(),s(g,null,{default:r(()=>[h(l,{id:"mermaid-17",class:"mermaid",graph:"xychart-beta%0A%20%20%20%20title%20%22%E4%BC%AF%E5%85%8B%E5%B8%8C%E5%B0%94%E6%AF%8F%E8%82%A1%E8%B4%A6%E9%9D%A2%E4%BB%B7%E5%80%BC%E5%A2%9E%E9%95%BF%EF%BC%88%E5%8D%83%E7%BE%8E%E5%85%83%EF%BC%89%22%0A%20%20%20%20x-axis%20%5B1965%2C%201975%2C%201985%2C%201995%2C%202005%2C%202015%2C%202024%5D%0A%20%20%20%20y-axis%20%22%E5%8D%83%E7%BE%8E%E5%85%83%2F%E8%82%A1%22%200%20--%3E%20450%0A%20%20%20%20bar%20%5B0.019%2C%200.093%2C%202.2%2C%2014.4%2C%2059.4%2C%20155.5%2C%20404.8%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<blockquote><p><strong>注意：</strong> 2024年数据（404.8千美元/股，即 $404,800/股）为估算值，实际数值以伯克希尔年报官方披露为准。</p></blockquote><h2 id="关键里程碑" tabindex="-1">关键里程碑 <a class="header-anchor" href="#关键里程碑" aria-label="Permalink to &quot;关键里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">时间</th><th>事件</th><th style="text-align:right;">账面价值/股</th></tr></thead><tbody><tr><td style="text-align:center;">1965</td><td>巴菲特接管伯克希尔</td><td style="text-align:right;">$19</td></tr><tr><td style="text-align:center;">1969</td><td>解散巴菲特合伙基金</td><td style="text-align:right;">$43</td></tr><tr><td style="text-align:center;">1979</td><td>突破 $500</td><td style="text-align:right;">$511</td></tr><tr><td style="text-align:center;">1988</td><td>突破 $3,000</td><td style="text-align:right;">$2,974</td></tr><tr><td style="text-align:center;">1998</td><td>突破 $40,000</td><td style="text-align:right;">$42,272</td></tr><tr><td style="text-align:center;">2007</td><td>突破 $100,000</td><td style="text-align:right;">$109,415</td></tr><tr><td style="text-align:center;">2016</td><td>突破 $170,000</td><td style="text-align:right;">$172,108</td></tr><tr><td style="text-align:center;">2024</td><td>突破 $400,000</td><td style="text-align:right;">$404,800</td></tr></tbody></table><h2 id="增长密码" tabindex="-1">增长密码 <a class="header-anchor" href="#增长密码" aria-label="Permalink to &quot;增长密码&quot;">​</a></h2><p>1965年至2024年，伯克希尔账面价值的<strong>年均复合增长率（CAGR）约为 19.8%</strong>，同期标普500指数（含分红）的年化回报约为 <strong>10.4%</strong>。这意味着：</p><ul><li>伯克希尔的增速几乎是市场的两倍</li><li>约每4年账面价值翻一番</li><li>如果1965年投资 $19,000（当时伯克希尔的整体估值约1,900万美元），持有至2024年，其价值将超过4亿美元</li></ul><p>巴菲特将这一超额回报归因于三点：<strong>（1）美国经济的顺风效应；（2）以合理价格买入优质企业的能力；（3）管理层保留盈利、持续复利再投资的机制。</strong></p><h2 id="关于账面价值的局限" tabindex="-1">关于账面价值的局限 <a class="header-anchor" href="#关于账面价值的局限" aria-label="Permalink to &quot;关于账面价值的局限&quot;">​</a></h2><p>巴菲特本人多次强调，账面价值并非衡量伯克希尔内在价值的完美指标。他在2018年致股东信中明确指出：</p><blockquote><p><em>&quot;账面价值是股票的 proxy（近似指标），而非内在价值的精确衡量……内在价值取决于公司在剩余存续期内能够产生的现金流。&quot;</em></p></blockquote><p>自2018年起，伯克希尔年报开始同时披露<strong>营业利润（Operating Earnings）</strong> 作为更准确的分析指标，不再将账面价值增速作为管理层薪酬的唯一考核基准。账面价值的局限性主要体现在：</p><ol><li><strong>账面价值受会计规则影响</strong>：历史成本记账的部分资产（如持有的股票组合）可能大幅偏离当前市场价值</li><li><strong>无法反映品牌价值与组织资本</strong>：伯克希尔的保险浮存金优势、企业文化与优秀子公司的价值难以量化</li><li><strong>股权结构差异</strong>：B股的存在使每股数据需做调整，历史数据的一致性受影响</li></ol><p>尽管如此，在缺乏更权威的统一估值框架前，账面价值仍是观察伯克希尔半个世纪成长轨迹最具参考性的单一指标。</p><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="https://www.berkshirehathaway.com/letters/letters.html" target="_blank" rel="noreferrer">巴菲特致股东信（1965-2024）</a> — 伯克希尔官方完整收录</li><li><a href="./market-cap-growth.html">伯克希尔市值变化：从纺织厂到万亿帝国</a> — 市值维度的增长轨迹</li><li><a href="./sp500-performance.html">与标普500业绩对比</a> — 复利奇迹的另一种验证</li></ul><hr><p><em>本页面数据基于公开资料整理，部分历史年份数据为合理估算。如有疏漏，欢迎指正。</em></p>',17))])}const y=o(c,[["render",p]]);export{C as __pageData,y as default};
